// Cuterus mascot image for the Save the Uterus Club OG card, inlined as a
// JPEG data URI so satori renders it without a network fetch at request time.
// Source: tools/generated-images/cuterus-real-a.png, center-cropped tight
// (sips -c 880 940) to enlarge the mascot in frame, then -Z 600 jpeg.
// Regenerate: sips -c 880 940 <mascot>.png -o crop.png && sips -s format jpeg -Z 600 crop.png -o c.jpg && base64 -i c.jpg
export const CUTERUS_OG = 'data:image/jpeg;base64,';
